internal static class UserBridge {
 [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr w,out uint p);
 [DllImport("user32.dll",SetLastError=true)] static extern uint SendInput(uint count,INPUT[] inputs,int size);
 [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr window);
 [DllImport("user32.dll")] static extern bool ShowWindow(IntPtr window,int command);
 [DllImport("user32.dll")] static extern bool PostMessage(IntPtr window,uint message,IntPtr w,IntPtr l);
 [StructLayout(LayoutKind.Sequential)] struct MOUSE {public int dx,dy;public uint data,flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Sequential)] struct KEY {public ushort vk,scan;public uint flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Explicit)] struct UNION {[FieldOffset(0)]public MOUSE mouse;[FieldOffset(0)]public KEY key;}
 [StructLayout(LayoutKind.Sequential)] struct INPUT {public uint type;public UNION data;}
 static readonly object Gate=new object();static readonly JavaScriptSerializer Json=new JavaScriptSerializer {MaxJsonLength=16384,RecursionLimit=12};static readonly Stopwatch Clock=Stopwatch.StartNew();
 static string ExpectedExe;static Process Target;static VirtualGamepad[] Pads;static string Backend;static bool Closing,Active;static long Epoch=-1,Sequence=-1,Last=-1000,LastFeedback;static HashSet<string> Held=new HashSet<string>();static bool? LastFocus;static readonly int[] Motors=new int[4];
 static readonly Dictionary<string,ushort> KeyCodes=BuildKeys();
 static Dictionary<string,ushort> BuildKeys(){var d=new Dictionary<string,ushort>();for(char c='A';c<='Z';c++)d[c.ToString()]=c;for(char c='0';c<='9';c++)d[c.ToString()]=c;for(int i=0;i<12;i++)d["F"+(i+1)]=(ushort)(0x70+i);for(int i=0;i<10;i++)d["Numpad"+i]=(ushort)(0x60+i);var names=new []{"ArrowUp","ArrowDown","ArrowLeft","ArrowRight","Space","Enter","Escape","Tab","Shift","Control","Alt","Backspace"};var codes=new ushort[]{0x26,0x28,0x25,0x27,0x20,0x0d,0x1b,0x09,0x10,0x11,0x12,0x08};for(int i=0;i<names.Length;i++)d[names[i]]=codes[i];d["Backquote"]=192;d["Minus"]=189;d["Equal"]=187;d["BracketLeft"]=219;d["BracketRight"]=221;d["Backslash"]=220;d["Semicolon"]=186;d["Quote"]=222;d["Comma"]=188;d["Period"]=190;d["Slash"]=191;d["Insert"]=45;d["Delete"]=46;d["Home"]=36;d["End"]=35;d["PageUp"]=33;d["PageDown"]=34;d["NumpadAdd"]=107;d["NumpadSubtract"]=109;d["NumpadMultiply"]=106;d["NumpadDivide"]=111;d["NumpadDecimal"]=110;d["NumpadEnter"]=13;d["ShiftLeft"]=160;d["ShiftRight"]=161;d["ControlLeft"]=162;d["ControlRight"]=163;d["AltLeft"]=164;d["AltRight"]=165;return d;}
 static void Emit(object value){Console.WriteLine(Json.Serialize(value));}
 static bool Focused(){uint pid;GetWindowThreadProcessId(GetForegroundWindow(),out pid);return Target!=null&&!Target.HasExited&&pid==Target.Id;}
 static void ApplyKeys(HashSet<string> wanted){bool alt=wanted.Any(k=>k=="Alt"||k=="AltLeft"||k=="AltRight"),ctrl=wanted.Any(k=>k=="Control"||k=="ControlLeft"||k=="ControlRight");if(alt){wanted.Remove("Space");wanted.Remove("F4");wanted.Remove("Tab");wanted.Remove("Escape");}if(ctrl)wanted.Remove("Escape");if(ctrl&&alt)wanted.Remove("Delete");var updates=new List<INPUT>();foreach(var key in Held.Except(wanted))updates.Add(KeyEvent(key,true));foreach(var key in wanted.Except(Held))updates.Add(KeyEvent(key,false));if(updates.Count>0&&SendInput((uint)updates.Count,updates.ToArray(),Marshal.SizeOf(typeof(INPUT)))!=updates.Count){Held.UnionWith(wanted);throw new InvalidOperationException("Windows did not accept all keyboard events. Check game focus and elevation.");}Held=wanted;}
 static INPUT KeyEvent(string name,bool up){return new INPUT{type=1,data=new UNION{key=new KEY{vk=KeyCodes[name],flags=(up?2u:0u)+((name.StartsWith("Arrow")||new[]{"Insert","Delete","Home","End","PageUp","PageDown","NumpadEnter","NumpadDivide","ControlRight","AltRight"}.Contains(name))?1u:0u)}}};}
 static void Neutral(){Active=false;if(Pads!=null)for(int i=0;i<Pads.Length;i++){if(Pads[i]!=null)Pads[i].Reset();if(Motors[i]!=0)Emit(new{type="rumble",epoch=Epoch,slot=i+1,largeMotor=0,smallMotor=0});Motors[i]=0;}if(Held.Count>0){try{ApplyKeys(new HashSet<string>());}catch{}}}
 static object Get(Dictionary<string,object> o,string k){object v;if(!o.TryGetValue(k,out v))throw new FormatException();return v;}
 static long Integer(object v){if(!(v is int)&&!(v is long))throw new FormatException();long n=Convert.ToInt64(v);if(n<0||n>9007199254740991L)throw new FormatException();return n;}
 static double Axis(Dictionary<string,object> o,string k,bool trigger=false){var v=Get(o,k);if(!(v is int)&&!(v is long)&&!(v is decimal)&&!(v is double))throw new FormatException();double n=Convert.ToDouble(v);if(Double.IsNaN(n)||Double.IsInfinity(n)||n<(trigger?0:-1)||n>1)throw new FormatException();return n;}
 static readonly Dictionary<string,ushort> Bits=new Dictionary<string,ushort>{{"up",1},{"down",2},{"left",4},{"right",8},{"start",16},{"select",32},{"ls",64},{"rs",128},{"l",256},{"r",512},{"a",4096},{"b",8192},{"x",16384},{"y",32768}};
 internal static VirtualGamepad.Report ParseReport(Dictionary<string,object> p,HashSet<string> keys){var buttons=Get(p,"buttons") as object[];var keyNames=Get(p,"keys") as object[];var a=Get(p,"axes") as Dictionary<string,object>;if(buttons==null||buttons.Length>14||keyNames==null||keyNames.Length>64||a==null||a.Count!=6)throw new FormatException();var seen=new HashSet<string>();var report=new VirtualGamepad.Report();foreach(var b in buttons){var name=b as string;if(name==null||!Bits.ContainsKey(name)||!seen.Add(name))throw new FormatException();report.buttons|=Bits[name];}foreach(var k in keyNames){var name=k as string;if(name==null||!KeyCodes.ContainsKey(name))throw new FormatException();keys.Add(name);}report.leftX=(short)Math.Round(Axis(a,"lx")*32767);report.leftY=(short)Math.Round(Axis(a,"ly")*32767);report.rightX=(short)Math.Round(Axis(a,"rx")*32767);report.rightY=(short)Math.Round(Axis(a,"ry")*32767);report.leftTrigger=(byte)Math.Round(Axis(a,"lt",true)*255);report.rightTrigger=(byte)Math.Round(Axis(a,"rt",true)*255);return report;}
 static void ReadFrame(string line,int count){var frame=Json.DeserializeObject(line) as Dictionary<string,object>;if(frame==null)throw new FormatException();string type=Get(frame,"type") as string;if(type=="attach"){if(Target!=null)throw new FormatException();int pid=checked((int)Integer(Get(frame,"pid")));Target=Process.GetProcessById(pid);if(pid==Process.GetCurrentProcess().Id||!String.Equals(Path.GetFullPath(Target.MainModule.FileName),ExpectedExe,StringComparison.OrdinalIgnoreCase))throw new ArgumentException("The process does not match the approved game.");Emit(new{type="attached"});return;}if(type=="focus"){if(Target==null)throw new FormatException();Neutral();Target.Refresh();ShowWindow(Target.MainWindowHandle,9);SetForegroundWindow(Target.MainWindowHandle);return;}if(type=="close"){if(Target==null)throw new FormatException();Neutral();Target.Refresh();if(Target.MainWindowHandle!=IntPtr.Zero)PostMessage(Target.MainWindowHandle,0x0010,IntPtr.Zero,IntPtr.Zero);return;}if(type!="output"||Integer(Get(frame,"version"))!=2)throw new FormatException();long epoch=Integer(Get(frame,"epoch")),seq=Integer(Get(frame,"seq"));if(epoch<Epoch||epoch==Epoch&&seq<=Sequence){Neutral();return;}var entries=Get(frame,"players") as object[];if(entries==null||entries.Length!=count)throw new FormatException();var reports=new VirtualGamepad.Report[count];var keys=new HashSet<string>();var slots=new HashSet<int>();foreach(var entry in entries){var player=entry as Dictionary<string,object>;if(player==null)throw new FormatException();long slotNumber=Integer(Get(player,"slot"));if(slotNumber<1||slotNumber>count)throw new FormatException();int slot=(int)slotNumber;if(!slots.Add(slot))throw new FormatException();reports[slot-1]=ParseReport(player,keys);}bool barrier=epoch!=Epoch;Epoch=epoch;Sequence=seq;Last=Clock.ElapsedMilliseconds;if(barrier||!Focused()){Neutral();return;}if(Pads!=null)for(int i=0;i<count;i++){Pads[i].WantReport(reports[i]);Pads[i].Apply();}if(Backend=="keyboard")ApplyKeys(keys);Active=true;}
 static string ReadLine(){var s=new StringBuilder();while(true){int c=Console.In.Read();if(c<0)return s.Length==0?null:s.ToString();if(c=='\n')return s.ToString().TrimEnd('\r');if(s.Length>=16384)throw new FormatException();s.Append((char)c);}}
 static void Tick(object ignored){lock(Gate){if(Closing)return;try{if(Target==null)return;if(Target.HasExited){Neutral();Closing=true;Emit(new{type="exited"});return;}bool focus=Focused();if(!focus||Clock.ElapsedMilliseconds-Last>300)Neutral();else if(Active&&Pads!=null)foreach(var pad in Pads)pad.Apply();if(LastFocus!=focus){LastFocus=focus;Emit(new{type="focus",focused=focus});}if(Pads!=null&&Clock.ElapsedMilliseconds-LastFeedback>=80){LastFeedback=Clock.ElapsedMilliseconds;for(int i=0;i<Pads.Length;i++){if(!Pads[i].Available)throw new Exception("Virtual controller disconnected.");int motors=focus&&Active?Pads[i].ReadMotors():0;if(motors!=0||motors!=Motors[i])Emit(new{type="rumble",epoch=Epoch,slot=i+1,largeMotor=motors&255,smallMotor=motors>>8});Motors[i]=motors;}}}catch{Neutral();Closing=true;Emit(new{type="error",message="The game input connection stopped."});}}}
 static int SelfTest(){int checks=0;Action<bool> check=v=>{if(!v)throw new Exception("User bridge self-test failed at "+checks);checks++;};check(Marshal.SizeOf(typeof(INPUT))==40);check(KeyCodes.Count==99);check(KeyEvent("NumpadEnter",false).data.key.flags==1);check(KeyEvent("Enter",false).data.key.flags==0);check(KeyEvent("ControlRight",true).data.key.flags==3);check(KeyCodes["Comma"]==188&&KeyCodes["ShiftRight"]==161);var keySet=new HashSet<string>();var report=ParseReport((Dictionary<string,object>)Json.DeserializeObject("{\"buttons\":[\"a\",\"r\"],\"keys\":[\"W\"],\"axes\":{\"lx\":0.5,\"ly\":-1,\"rx\":0,\"ry\":0,\"lt\":0.25,\"rt\":1}}"),keySet);check(report.leftX==16384&&report.leftY==-32767);check(report.leftTrigger==64&&report.rightTrigger==255);check(report.buttons==0x1200&&keySet.Contains("W"));foreach(var bad in new[]{"{\"buttons\":[\"shell\"],\"keys\":[],\"axes\":{}}","{\"buttons\":[],\"keys\":[\"Meta\"],\"axes\":{}}"}){bool rejected=false;try{ParseReport((Dictionary<string,object>)Json.DeserializeObject(bad),keySet);}catch{rejected=true;}check(rejected);}Emit(new{type="self-test",checks=checks,nativeDevicesCreated=false});return 0;}
 static int Main(string[] args){Console.OutputEncoding=new UTF8Encoding(false);try{if(args.SequenceEqual(new[]{"--self-test"}))return SelfTest();if(args.Length==2&&args[0]=="--find"){string file=Path.GetFullPath(args[1]);var found=new List<object>();foreach(var process in Process.GetProcesses()){try{if(String.Equals(Path.GetFullPath(process.MainModule.FileName),file,StringComparison.OrdinalIgnoreCase))found.Add(new{pid=process.Id,title=process.MainWindowTitle,window=process.MainWindowHandle!=IntPtr.Zero});}catch{}finally{process.Dispose();}}Emit(new{type="processes",processes=found});return 0;}if(args.SequenceEqual(new[]{"--probe"})){using(var probe=new VirtualGamepad()){Emit(new{type="probe",keyboard=true,gamepad=probe.Available,message=probe.Message});return 0;}}if(args.Length!=8||args[0]!="--pid"||args[2]!="--exe"||args[4]!="--players"||args[6]!="--backend")throw new ArgumentException("Use --probe, --self-test, or --pid PID --exe ABSOLUTE --players 1..4 --backend keyboard|gamepad.");int pid,count;if(!Int32.TryParse(args[1],out pid)||pid<0||!Int32.TryParse(args[5],out count)||count<1||count>4)throw new ArgumentException("Invalid process/player count.");Backend=args[7];if(Backend!="keyboard"&&Backend!="gamepad")throw new ArgumentException("Invalid backend.");if(!Path.IsPathRooted(args[3])||!String.Equals(Path.GetExtension(args[3]),".exe",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Choose the game executable.");ExpectedExe=Path.GetFullPath(args[3]);if(pid>0){Target=Process.GetProcessById(pid);if(Target.Id==Process.GetCurrentProcess().Id||!String.Equals(ExpectedExe,Path.GetFullPath(Target.MainModule.FileName),StringComparison.OrdinalIgnoreCase))throw new ArgumentException("The process does not match the approved executable.");}if(Backend=="gamepad"){Pads=new VirtualGamepad[count];for(int i=0;i<count;i++){Pads[i]=new VirtualGamepad(i+1);if(!Pads[i].EnsureTarget())throw new InvalidOperationException(Pads[i].Message);}}Emit(new{type="ready",slots=Pads==null?null:Pads.Select((p,i)=>new{slot=i+1,xinputIndex=p.UserIndex}).ToArray()});using(var timer=new Timer(Tick,null,0,15)){string line;long rateStart=Clock.ElapsedMilliseconds;int rate=0;while((line=ReadLine())!=null){lock(Gate){if(Closing)break;if(Clock.ElapsedMilliseconds-rateStart>=1000){rate=0;rateStart=Clock.ElapsedMilliseconds;}if(++rate>240)throw new FormatException();ReadFrame(line,count);}}}return 0;}catch(Exception error){Emit(new{type="error",message=error is FormatException?"Invalid output frame; input stopped.":error.Message});return 1;}finally{lock(Gate){Closing=true;Neutral();if(Pads!=null)foreach(var p in Pads)if(p!=null)p.Dispose();if(Target!=null)Target.Dispose();}}}
}
